@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');

/* Terminal — black bg, phosphor green, IBM Plex Mono, ASCII-ish borders */
.theme-terminal {
  --bg: oklch(0.13 0.015 150);
  --surface: oklch(0.17 0.02 150);
  --surface-2: oklch(0.21 0.025 150);
  --fg: oklch(0.88 0.2 145);
  --fg-muted: oklch(0.66 0.14 145);
  --accent: oklch(0.85 0.22 145);
  --accent-fg: oklch(0.13 0.015 150);
  --accent-2: oklch(0.8 0.16 195);
  --line: oklch(0.85 0.22 145 / 35%);
  --success: oklch(0.85 0.22 145);
  --warning: oklch(0.85 0.18 95);
  --danger: oklch(0.68 0.22 25);

  --radius: 0rem;
  --radius-sm: 0rem;
  --radius-lg: 0rem;
  --radius-pill: 0rem;

  --shadow-1: 0 0 0 1px var(--line);
  --shadow-2: 0 0 18px -4px color-mix(in oklab, var(--accent) 45%, transparent);
  --shadow-3: 0 0 34px -6px color-mix(in oklab, var(--accent) 55%, transparent);
  --glow: 0 0 14px -2px color-mix(in oklab, var(--accent) 70%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "IBM Plex Mono", ui-monospace, monospace;
  --font-body: "IBM Plex Mono", ui-monospace, monospace;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: 0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.16em;

  background-color: var(--bg);
  background-image: repeating-linear-gradient(
    to bottom,
    oklch(0.85 0.22 145 / 5%) 0px,
    oklch(0.85 0.22 145 / 5%) 1px,
    transparent 1px,
    transparent 3px
  );
  color: var(--fg);
  font-family: var(--font-body);
  text-shadow: 0 0 6px color-mix(in oklab, var(--accent) 30%, transparent);
}

.theme-terminal h1,
.theme-terminal h2,
.theme-terminal h3 {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-terminal { background-image: repeating-linear-gradient(0deg, transparent 0 2px, oklch(0 0 0 / 22%) 2px 4px); }
.theme-terminal h1::after { content: "_"; margin-left: 0.1em; animation: sf-blink 1.1s steps(1) infinite; }
.theme-terminal h1, .theme-terminal h2, .theme-terminal h3 { text-transform: lowercase; }
.theme-terminal button { text-transform: lowercase; }
.theme-terminal ::selection { background: var(--accent); color: oklch(0.1 0 0); }

/* depth */
.theme-terminal thead th { font-weight: 400; text-transform: lowercase; color: var(--accent); border-bottom: 1px dashed var(--line); background: transparent; letter-spacing: 0.08em; }
.theme-terminal td { border-bottom: 1px solid oklch(0.85 0.22 145 / 12%); }
.theme-terminal tbody tr:hover { background: oklch(0.85 0.22 145 / 8%); }
.theme-terminal input, .theme-terminal select, .theme-terminal textarea { background: oklch(0 0 0 / 30%); border: 1px solid var(--line); border-radius: 0; caret-color: var(--accent); text-shadow: none; }
.theme-terminal input:focus-visible, .theme-terminal select:focus-visible, .theme-terminal textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
/* inverse video — the terminal's only emphasis */
.theme-terminal kbd { font-family: var(--font-mono); background: var(--accent); color: var(--accent-fg); text-shadow: none; padding: 0.05em 0.4em; border-radius: 0; }
.theme-terminal a { color: var(--accent); text-decoration: underline dotted; text-underline-offset: 3px; }
.theme-terminal a:hover { background: var(--accent); color: var(--accent-fg); text-decoration: none; text-shadow: none; }
.theme-terminal ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-terminal ::-webkit-scrollbar-track { background: var(--bg); box-shadow: inset 1px 0 0 var(--line); }
.theme-terminal ::-webkit-scrollbar-thumb { background: var(--fg-muted); border: 3px solid var(--bg); border-radius: 0; }
.theme-terminal ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-terminal .label-caps { text-transform: lowercase; color: var(--fg-muted); letter-spacing: 0.16em; }
.theme-terminal .label-caps::before { content: "> "; color: var(--accent); }
/* ASCII double-rule frame */
.theme-terminal .themed-border { border-style: solid; outline: 1px solid oklch(0.85 0.22 145 / 15%); outline-offset: 3px; }
.theme-terminal button:active { background: var(--accent); color: var(--accent-fg); text-shadow: none; }

.theme-terminal.alt-mode { --bg: oklch(0.96 0.01 120); --surface: oklch(0.93 0.012 120); --surface-2: oklch(0.89 0.015 120);
  --fg: oklch(0.35 0.09 145); --fg-muted: oklch(0.5 0.06 145); --line: oklch(0.35 0.09 145 / 35%);
  --accent: oklch(0.42 0.12 145); --accent-fg: oklch(0.97 0.01 120);
  background-image: repeating-linear-gradient(0deg, transparent 0 2px, oklch(0.35 0.09 145 / 5%) 2px 4px);
  text-shadow: none; /* no phosphor bloom on paper — dot-matrix printout, crisp ink */ }
.theme-terminal.alt-mode td { border-bottom-color: oklch(0.35 0.09 145 / 15%); }
.theme-terminal.alt-mode tbody tr:hover { background: oklch(0.35 0.09 145 / 8%); }
.theme-terminal.alt-mode input, .theme-terminal.alt-mode select, .theme-terminal.alt-mode textarea { background: oklch(1 0 0 / 55%); }
.theme-terminal.alt-mode .themed-border { outline-color: oklch(0.35 0.09 145 / 20%); }
.theme-terminal.alt-mode ::-webkit-scrollbar-track { background: var(--bg); }
.theme-terminal.alt-mode ::-webkit-scrollbar-thumb { border-color: var(--bg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
